Think: Create cleaned files clean_<filename> from each temp_workspace/raw_<filename> by converting non-digit/non-minus chars to spaces, keeping minus signs only when adjacent to digits, collapsing runs of spaces to single spaces, trimming, and writing outputs into temp_workspace.

Act: bash

```bash
awk '{
 s=$0; res=""; n=length(s);
 for(i=1;i<=n;i++){
  c=substr(s,i,1);
  if(c~/[0-9]/) res = res c;
  else if(c=="-"){
    prev=(i>1?substr(s,i-1,1):"");
    nextc=(i<n?substr(s,i+1,1):"");
    if(prev~/[0-9]/ || nextc~/[0-9]/) res = res "-"; else res = res " ";
  } else res = res " ";
 }
 gsub(/[[:space:]]+/, " ", res);
 gsub(/^ +| +$/,"", res);
 out=FILENAME; sub(/^.*\//,"",out); out="temp_workspace/clean_" out;
 print res > out;
 close(out);
}' temp_workspace/raw_*
