Think: Validate each file listed in file_list.txt so that files whose every line has exactly four whitespace-separated tokens are recorded in valid_files.txt and others in invalid_files.txt.

Act: bash

```bash
awk '{
 f=$0; ok=1;
 while((getline line < f) > 0) {
   n=split(line,a,/[[:space:]]+/);
   if(n!=4){ ok=0; break }
 }
 if(ok) print f >> "temp_student_processing/valid_files.txt"; else print f >> "temp_student_processing/invalid_files.txt";
 close(f)
}' temp_student_processing/file_list.txt
